 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-APPS-003",
   "status_as_recorded": "artifact",
   "finding": "The V4 engine's recommended play type (against team modal) had a 69.8% hit rate (37/53), but this was an artifact due to using banned play types (DRIVE) and tuning on the same series. No holdout result was recorded. The 69.8% (37/53) hit rate was inflated: 14 of 53 pairs compared against the banned DRIVE, 13 of 37 hits came from CUT, and the same series were used to find the DRIVE failure and tune the exclusion."
  },
  {
   "id": "FAM:SF-APPS-018",
   "status_as_recorded": "inconclusive",
   "finding": "Tested the playsheet counter ranking in 10 completed 2025-26 playoff series (665 counter observations, average 6.9 possessions per counter). The full-rank Spearman was not significant (rho -0.0639, p=0.099717). BEST vs AVOID strategies differed significantly (Mann-Whitney U=5546.0, p=0.004018)."
  },
  {
   "id": "FAM:SF-APPS-068",
   "status_as_recorded": "artifact",
   "finding": "The Possession Control Index (PCI) showed an incremental R2 gain (+0.139) over ORtg in explaining Net Rating (120 team-seasons), but this gain was an artifact from a leakage term highly correlated with DRtg (corr +0.894). Offensive-control components added only +0.005 R2."
